SELECT QUARTER(products.launch_date) AS launch_quarter, MAX(store_sales.revenue) - MIN(store_sales.revenue) AS revenue_range, COUNT(store_sales.units) AS units_count FROM store_sales LEFT JOIN products ON store_sales.product_id = products.id INNER JOIN suppliers ON suppliers.id = products.supplier_id WHERE products.supplier_id IS NOT NULL GROUP BY QUARTER(products.launch_date) ORDER BY units_count ASC, launch_quarter ASC LIMIT 50
